changeSet.sql:
CREATE TABLE domain_record (kind VARCHAR(32) NOT NULL, record_key VARCHAR(100) NOT NULL, owner_id VARCHAR(36) NOT NULL, payload CLOB NOT NULL, version BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(kind,record_key));
CREATE TABLE resource_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, object_id VARCHAR(100) NOT NULL, field_name VARCHAR(80) NOT NULL, field_value VARCHAR(1000) NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_resource_history ON resource_history(object_id,recorded_at);
CREATE TABLE operational_report (id VARCHAR(36) PRIMARY KEY, callsign VARCHAR(100) NOT NULL, kind VARCHAR(40) NOT NULL, payload CLOB NOT NULL, wire VARCHAR(2000) NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL, remote BOOLEAN NOT NULL);
CREATE INDEX ix_operational_report ON operational_report(callsign,kind,recorded_at);
CREATE TABLE raw_packet (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, instance_id VARCHAR(36) NOT NULL, source VARCHAR(16) NOT NULL, packet VARCHAR(4096) NOT NULL, received_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX ix_packet_time ON raw_packet(received_at,id);
CREATE TABLE activity (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor VARCHAR(100) NOT NULL, description VARCHAR(500) NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE net_question (id VARCHAR(36) PRIMARY KEY, net_id VARCHAR(36) NOT NULL REFERENCES managed_net(id), number INT NOT NULL, callsign VARCHAR(9) NOT NULL, question VARCHAR(500) NOT NULL, asked_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(net_id,number));
CREATE TABLE net_answer (question_id VARCHAR(36) NOT NULL REFERENCES net_question(id), callsign VARCHAR(9) NOT NULL, answer VARCHAR(500) NOT NULL, answered_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(question_id,callsign));
ALTER TABLE net_participant ADD transmit_power VARCHAR(20) NOT NULL DEFAULT '';
ALTER TABLE net_participant ADD electrical_power VARCHAR(20) NOT NULL DEFAULT '';
ALTER TABLE net_participant ADD backup_power VARCHAR(20) NOT NULL DEFAULT '';
ALTER TABLE net_participant ADD radio_style VARCHAR(20) NOT NULL DEFAULT '';
ALTER TABLE net_participant ADD notify_changes BOOLEAN NOT NULL DEFAULT FALSE;
INSERT INTO application_settings VALUES('operations.stationRetentionSeconds','86400');
INSERT INTO application_settings VALUES('operations.packetRetentionSeconds','604800');
INSERT INTO application_settings VALUES('operations.packetLimit','100000');
INSERT INTO application_settings VALUES('operations.rawPacketLogging','false');
INSERT INTO application_settings VALUES('operations.federationEnabled','false');
INSERT INTO application_settings VALUES('operations.beaconSeconds','600');
INSERT INTO application_settings VALUES('operations.reminderSeconds','1800');
INSERT INTO application_settings VALUES('operations.netManagerEnabled','false');
INSERT INTO application_settings VALUES('operations.netManagerCallsign','');
INSERT INTO application_settings VALUES('operations.netManagerOwner','');
